                        let (count, bytes) = rt_db::torrent_tracker_snapshot_size(db, &info_hash)
                            .map_err(|error| error.to_string())?;
                        validate_tracker_snapshot_size(count, bytes)?;
                        rt_db::list_torrent_tracker_urls(db, &info_hash)
                            .map_err(|error| error.to_string())
