    fn completed_storage_plan_steps(&self, job_id: &str) -> Vec<usize> {
        let db = self.db.lock().expect("database mutex poisoned");
        let Ok(job) = rt_db::get_job(&db, job_id) else {
            return Vec::new();
        };
        if job.kind != JOB_KIND_STORAGE_PLAN {
            return Vec::new();
        }
        let checkpoint = job.checkpoint.max(0) as usize;
        (0..checkpoint).collect()
    }

    /// Commit a job projection and all events describing that update as one
    /// SQLite transaction. A job state without its event is not an auditable
    /// state transition and can make restart recovery choose the wrong path.
    async fn persist_job_with_events_async(
        &self,
        job: &rt_db::JobRow,
        events: &[rt_db::JobEventRow],
    ) -> Result<(), String> {
        let job = job.clone();
        let events = events.to_vec();
        self.run_db("persist_job_with_events", move |db| {
            let tx = db.transaction().map_err(|error| error.to_string())?;
            rt_db::upsert_job_in_tx(&tx, &job).map_err(|error| error.to_string())?;
            for event in &events {
                rt_db::append_job_event_in_tx(&tx, event).map_err(|error| error.to_string())?;
            }
            tx.commit().map_err(|error| error.to_string())
        })
        .await
    }

    #[cfg(test)]
    fn persist_job_with_events(
        &self,
        job: &rt_db::JobRow,
        events: &[rt_db::JobEventRow],
    ) -> Result<(), String> {
        let mut db = self.db.lock().expect("database mutex poisoned");
        let tx = db.transaction().map_err(|error| error.to_string())?;
        rt_db::upsert_job_in_tx(&tx, job).map_err(|error| error.to_string())?;
        for event in events {
            rt_db::append_job_event_in_tx(&tx, event).map_err(|error| error.to_string())?;
        }
        tx.commit().map_err(|error| error.to_string())
    }

    async fn update_job_state_async(
        &self,
        job_id: &str,
        state: &str,
        error: Option<String>,
        message: Option<&str>,
    ) -> Result<(), String> {
        self.update_job_state_async_with_run_token(job_id, state, error, message, None)
            .await
            .map(|_| ())
    }

    async fn update_job_state_async_with_run_token(
        &self,
        job_id: &str,
        state: &str,
        error: Option<String>,
        message: Option<&str>,
        run_token: Option<u64>,
    ) -> Result<JobStateUpdateMarker, String> {
        let job_id_for_db = job_id.to_owned();
        let state = state.to_owned();
        let message = message.map(str::to_owned);
        self.run_db("persist_job_state", move |db| {
            let tx = db
                .transaction_with_behavior(TransactionBehavior::Immediate)
                .map_err(|error| error.to_string())?;
            let mut job = rt_db::get_job(&tx, &job_id_for_db).map_err(|error| error.to_string())?;
            if job.finished_at.is_some()
                || matches!(
                    job.state.as_str(),
                    JOB_STATE_CANCELLED | JOB_STATE_COMPLETED | JOB_STATE_FAILED
                )
            {
                if job.state == state {
                    // Existing callers treat an idempotent terminal update as
                    // success. No control handoff uses this path, so there
                    // is no event marker to return for a rollback fence.
                    return Ok(JobStateUpdateMarker {
                        updated_at: job.updated_at,
                        event_id: 0,
                    });
                }
                return Err(format!("job {job_id_for_db} is already terminal"));
            }
            let now = unix_now_i64();
            job.state = state.clone();
            job.error = error;
            job.updated_at = now;
            if state == JOB_STATE_RUNNING && job.started_at.is_none() {
                job.started_at = Some(now);
            }
            if matches!(
                state.as_str(),
                JOB_STATE_CANCELLED | JOB_STATE_FAILED | JOB_STATE_COMPLETED
            ) {
                job.finished_at = Some(now);
            }
            let state_payload = match run_token {
                Some(run_token) => serde_json::json!({
                    "state": state,
                    "run_token": run_token,
                }),
                None => serde_json::json!({ "state": state }),
            };
            let event = rt_db::JobEventRow {
                event_id: None,
                job_id: job_id_for_db.clone(),
                occurred_at: now,
                kind: format!("job_{state}"),
                message,
                payload: state_payload.to_string(),
            };
            let started = (state == JOB_STATE_RUNNING).then(|| rt_db::JobEventRow {
                event_id: None,
                job_id: job_id_for_db.clone(),
                occurred_at: now,
                kind: "check_started".to_owned(),
                message: Some("recheck started".to_owned()),
                payload: state_payload.to_string(),
            });
            let mut events = vec![event];
            if let Some(started) = started {
                events.push(started);
            }
            rt_db::upsert_job_in_tx(&tx, &job).map_err(|error| error.to_string())?;
            let mut event_id = 0;
            for event in &events {
                event_id =
                    rt_db::append_job_event_in_tx(&tx, event).map_err(|error| error.to_string())?;
            }
            tx.commit().map_err(|error| error.to_string())?;
            Ok(JobStateUpdateMarker {
                updated_at: now,
                event_id,
            })
        })
        .await
    }

    async fn update_job_state_best_effort(
        &self,
        job_id: &str,
        state: &str,
        error: Option<String>,
        message: Option<&str>,
    ) {
        if let Err(update_error) = self
            .update_job_state_async(job_id, state, error, message)
            .await
        {
            warn!(
                component = "db",
                operation = "persist_job_state",
                job_id,
                state,
                result = "error",
                error = %update_error,
                "failed to persist best-effort job state transition"
            );
        }
    }

    #[cfg(test)]
    fn update_job_state(
        &self,
        job_id: &str,
        state: &str,
        error: Option<String>,
        message: Option<&str>,
    ) {
        let now = unix_now_i64();
        let mut job = {
            let db = self.db.lock().expect("database mutex poisoned");
            match rt_db::get_job(&db, job_id) {
                Ok(job) => job,
                Err(e) => {
                    warn!(
                        component = "db",
                        operation = "load_job_for_state_update",
                        job_id,
                        result = "error",
                        error = %e,
                        "failed to load job for state update"
                    );
                    return;
                }
            }
        };
        job.state = state.to_owned();
        job.error = error;
        job.updated_at = now;
        if state == JOB_STATE_RUNNING && job.started_at.is_none() {
            job.started_at = Some(now);
        }
        if matches!(state, JOB_STATE_CANCELLED | JOB_STATE_FAILED) {
            job.finished_at = Some(now);
        }
        let event = rt_db::JobEventRow {
            event_id: None,
            job_id: job_id.to_owned(),
            occurred_at: now,
            kind: format!("job_{state}"),
            message: message.map(str::to_owned),
            payload: serde_json::json!({ "state": state }).to_string(),
        };
        let started = (state == JOB_STATE_RUNNING).then(|| rt_db::JobEventRow {
            event_id: None,
            job_id: job_id.to_owned(),
            occurred_at: now,
            kind: "check_started".to_owned(),
            message: Some("recheck started".to_owned()),
            payload: serde_json::json!({ "state": state }).to_string(),
        });
        let mut events = vec![event];
        if let Some(started) = started {
            events.push(started);
        }
        if let Err(e) = self.persist_job_with_events(&job, &events) {
            warn!(
                component = "db",
                operation = "persist_job_state",
                job_id,
                state,
                result = "error",
                error = %e,
                "failed to persist job state and event atomically"
            );
        }
    }

    async fn persist_pure_v2_recheck_job_async(
        &self,
        job_id: &str,
        done: i64,
        total: i64,
        invalid_files: &[i64],
    ) -> CmdResult<()> {
        let job_id_for_db = job_id.to_owned();
        let mut job = self
            .run_db("load_pure_v2_recheck_job", move |db| {
                rt_db::get_job(db, &job_id_for_db).map_err(|error| {
                    format!("failed to load pure v2 recheck job {job_id_for_db}: {error}")
                })
            })
            .await?;
        let now = unix_now_i64();
        job.total = total;
        job.done = done;
        job.checkpoint = done;
        job.file_index = Some(done);
        job.piece_index = None;
        job.byte_offset = None;
        let invalid_file_count = invalid_files.len();
        let invalid_files_truncated = invalid_file_count > rt_db::MAX_JOB_INVALID_PIECES;
        let invalid_files = invalid_files
            .iter()
            .copied()
            .take(rt_db::MAX_JOB_INVALID_PIECES)
            .collect::<Vec<_>>();
        job.invalid_pieces = invalid_files.clone();
        job.state = JOB_STATE_COMPLETED.to_owned();
        job.updated_at = now;
        job.finished_at = Some(now);
        let event = rt_db::JobEventRow {
            event_id: None,
            job_id: job_id.to_owned(),
            occurred_at: now,
            kind: "check_completed".to_owned(),
            message: Some("pure v2 file-root recheck completed".to_owned()),
            payload: serde_json::json!({
                "done": done,
                "total": total,
                "invalid_file_count": invalid_file_count,
                "invalid_files_truncated": invalid_files_truncated,
                "invalid_files": invalid_files,
                "state": JOB_STATE_COMPLETED,
            })
            .to_string(),
        };
        self.persist_job_with_events_async(&job, &[event])
            .await
            .map_err(|error| {
                format!(
                    "failed to persist pure v2 recheck job {job_id} and completion event: {error}"
                )
            })
    }

