fn metadata_from_meta(meta: &TorrentMeta) -> EngineTorrentMetadata {
    match meta {
        TorrentMeta::V1(meta) => EngineTorrentMetadata {
            piece_length: meta.piece_length,
            piece_count: meta.pieces.len(),
            piece_hashes: meta.pieces.iter().map(hex::encode).collect(),
            piece_states: vec![EnginePieceState::Missing; meta.pieces.len()],
            is_private: meta.private,
            trackers: meta.all_trackers(),
            webseeds: meta.webseeds.clone(),
            comment: meta.comment.clone(),
            created_by: meta.created_by.clone(),
            creation_date: meta.creation_date,
            files: meta
                .files
                .iter()
                .map(|file| EngineTorrentFile {
                    index: file.index,
                    path: file.path.as_display(),
                    length: file.length,
                    priority: 1,
                    wanted: true,
                })
                .collect(),
        },
        TorrentMeta::Hybrid(meta, _) => EngineTorrentMetadata {
            piece_length: meta.piece_length,
            piece_count: meta.pieces.len(),
            piece_hashes: meta.pieces.iter().map(hex::encode).collect(),
            piece_states: vec![EnginePieceState::Missing; meta.pieces.len()],
            is_private: meta.private,
            trackers: meta.all_trackers(),
            webseeds: meta.webseeds.clone(),
            comment: meta.comment.clone(),
            created_by: meta.created_by.clone(),
            creation_date: meta.creation_date,
            files: meta
                .files
                .iter()
                .map(|file| EngineTorrentFile {
                    index: file.index,
                    path: file.path.as_display(),
                    length: file.length,
                    priority: 1,
                    wanted: true,
                })
                .collect(),
        },
        TorrentMeta::V2(meta) => {
            // Pure-v2 pieces live in the logical address space, which
            // includes alignment gaps between files. Using total payload
            // bytes here under-reports the bitmap for multi-file torrents
            // with a gap and makes the API projection disagree with the
            // actor's V2PieceMap.
            let piece_count = usize::try_from(meta.piece_count()).unwrap_or(usize::MAX);
            EngineTorrentMetadata {
                piece_length: meta.piece_length,
                piece_count,
                piece_hashes: vec![String::new(); piece_count],
                piece_states: vec![EnginePieceState::Missing; piece_count],
                is_private: meta.private,
                trackers: v2_all_trackers(meta),
                webseeds: meta.webseeds.clone(),
                comment: meta.comment.clone(),
                created_by: meta.created_by.clone(),
                creation_date: meta.creation_date,
                files: meta
                    .files
                    .iter()
                    .map(|file| EngineTorrentFile {
                        index: file.index,
                        path: file.path.as_display(),
                        length: file.length,
                        priority: 1,
                        wanted: true,
                    })
                    .collect(),
            }
        }
    }
}

