    #[cfg(unix)]
    #[test]
    fn storage_move_planning_does_not_skip_a_broken_payload_symlink() {
        use std::os::unix::fs::symlink;

        let temp = tempfile::tempdir().unwrap();
        let source_root = temp.path().join("old");
        let destination_root = temp.path().join("new");
        std::fs::create_dir_all(&source_root).unwrap();
        std::fs::create_dir_all(&destination_root).unwrap();
        let source = source_root.join("payload.bin");
        symlink("missing-payload.bin", &source).unwrap();
        let authority = ServerStorageRoots::from_configured_paths([
            source_root.clone(),
            destination_root.clone(),
        ])
        .unwrap();

        let plan = plan_torrent_payload_files_with_authority(
            &authority,
            &source_root,
            &destination_root,
            &[(
                rt_path::SafeRelPath::from_name("payload.bin", false).unwrap(),
                7,
            )],
        )
        .unwrap()
        .expect("a broken symlink must not be mistaken for a missing payload");

        assert_eq!(plan.steps.len(), 1);
        assert_eq!(plan.steps[0].source.as_deref(), Some(source.as_path()));
    }

    #[tokio::test]
    async fn storage_move_waits_for_live_task_root_handoff_before_completion() {
        let conn = Connection::open_in_memory().unwrap();
        rt_db::migrate(&conn).unwrap();
        let info_hash = "e".repeat(40);
        let old_save_path = PathBuf::from("/storage/old");
        let save_path = PathBuf::from("/storage/new");
        let now = unix_now_i64();
        rt_db::upsert(
            &conn,
            &TorrentRow {
                info_hash: info_hash.clone(),
                name: "payload".to_owned(),
                total_length: 1,
                piece_length: 1,
                piece_count: 1,
                is_private: false,
                save_path: old_save_path.to_string_lossy().into_owned(),
                category: None,
                tags: Vec::new(),
                state: TorrentState::Paused.as_str().to_owned(),
                added_at: now,
                completed_at: None,
                uploaded: 0,
                downloaded: 0,
                amount_left: 1,
                ratio: 0.0,
                trackers: Vec::new(),
            },
        )
        .unwrap();
        rt_db::upsert_job(
            &conn,
            &rt_db::JobRow {
                job_id: "storage-move-handoff".to_owned(),
                kind: JOB_KIND_STORAGE_PLAN.to_owned(),
                state: STORAGE_JOB_STATE_COMMIT_PENDING.to_owned(),
                dry_run: false,
                affected_torrents: vec![info_hash.clone()],
                total: 1,
                done: 1,
                checkpoint: 1,
                file_index: Some(1),
                piece_index: None,
                byte_offset: Some(1),
                verified_bytes: 0,
                invalid_pieces: Vec::new(),
                error: None,
                created_at: now,
                started_at: Some(now),
                updated_at: now,
                finished_at: None,
            },
        )
        .unwrap();

        let registry = Arc::new(RwLock::new(SessionRegistry::new()));
        let mut entry = TorrentEntry::new(
            info_hash.clone(),
            "payload".to_owned(),
            old_save_path.to_string_lossy().into_owned(),
        );
        entry.state = TorrentState::Paused;
        registry.write().await.add(entry).unwrap();

        // A quiesced actor can still have unrelated commands queued. Keep
        // its mailbox full so the completion path exercises the delivery
        // failure instead of accidentally succeeding through an empty slot.
        let (torrent_tx, mut torrent_rx) = mpsc::channel(1);
        torrent_tx.try_send(TorrentCmd::Shutdown).unwrap();
        let mut torrent_chans = HashMap::new();
        torrent_chans.insert(info_hash.clone(), torrent_tx);
        let (cmd_tx, cmd_rx) = mpsc::channel(1);
        let db = Arc::new(Mutex::new(conn));
        let mut engine = Engine {
            config: Arc::new(Config::default()),
            registry: Arc::clone(&registry),
            db: Arc::clone(&db),
            cmd_rx,
            cmd_tx,
            runtime: subsystems::EngineRuntimeState {
                torrent_chans,
                torrent_tasks: HashMap::new(),
                tier_controller: TierController::new(TierPolicy::default()),
                tier_last_active: HashMap::new(),
                pending_torrent_adds: HashSet::new(),
                pending_torrent_deletes: HashSet::new(),
                pending_torrent_promotions: std::collections::HashMap::new(),
            },
            services: subsystems::EngineSubsystems {
                dht_tx: None,
                resources: test_resource_governor(),
                network_budget: GlobalNetworkBudget::unlimited(),
                storage_jobs: StorageJobDispatcher::for_tests(),
                stats_cache: None,
            },
            pending_storage_moves: HashMap::new(),
            shutdown_reply: None,
        };

        let result = engine
            .finish_storage_move(
                "storage-move-handoff",
                &info_hash,
                None,
                old_save_path,
                save_path.clone(),
                Some(false),
                None,
                true,
                STORAGE_JOB_STATE_COMMIT_PENDING.to_owned(),
                None,
                vec![0],
                Some(1),
                false,
                0,
            )
            .await;
        assert!(
            result.is_err(),
            "a full live-task mailbox must block completion"
        );

        let registry_entry = registry.read().await.get(&info_hash).unwrap();
        assert_eq!(registry_entry.save_path, save_path.to_string_lossy());
        drop(registry_entry);
        {
            let db = db.lock().unwrap();
            assert_eq!(
                rt_db::get_job(&db, "storage-move-handoff").unwrap().state,
                STORAGE_JOB_STATE_COMMIT_PENDING
            );
            assert!(rt_db::get_job(&db, "storage-move-handoff")
                .unwrap()
                .finished_at
                .is_none());
        }

        let retry = tokio::time::timeout(Duration::from_secs(3), engine.cmd_rx.recv())
            .await
            .expect("storage move handoff retry was not scheduled")
            .expect("engine command channel closed");
        assert!(matches!(
            retry,
            EngineCmd::StorageMoveFinished {
                retry_attempt: 1,
                completed_byte_offset: Some(1),
                ..
            }
        ));
        assert!(
            torrent_rx.try_recv().is_ok(),
            "the filler must remain queued"
        );
    }

    #[tokio::test]
    async fn generic_storage_commit_pending_retries_durable_completion() {
        let info_hash = "f".repeat(40);
        let conn = Connection::open_in_memory().unwrap();
        rt_db::migrate(&conn).unwrap();
        let now = unix_now_i64();
        rt_db::upsert_job(
            &conn,
            &rt_db::JobRow {
                job_id: "generic-storage-commit-retry".to_owned(),
                kind: JOB_KIND_STORAGE_PLAN.to_owned(),
                state: STORAGE_JOB_STATE_COMMIT_PENDING.to_owned(),
                dry_run: false,
                affected_torrents: Vec::new(),
                total: 1,
                done: 1,
                checkpoint: 1,
                file_index: Some(1),
                piece_index: None,
                byte_offset: Some(7),
                verified_bytes: 0,
                invalid_pieces: Vec::new(),
                error: None,
                created_at: now,
                started_at: Some(now),
                updated_at: now,
                finished_at: None,
            },
        )
        .unwrap();
        let db = Arc::new(Mutex::new(conn));
        let (cmd_tx, cmd_rx) = mpsc::channel(4);
        let (torrent_tx, mut torrent_rx) = mpsc::channel(4);
        let (resume_seen_tx, mut resume_seen_rx) = mpsc::channel(4);
        let resume_task = tokio::spawn(async move {
            while let Some(command) = torrent_rx.recv().await {
                if let TorrentCmd::ResumeAfterStorageMove { reply, .. } = command {
                    let _ = reply.send(Ok(()));
                    let _ = resume_seen_tx.send(()).await;
                }
            }
        });
        let mut engine = Engine {
            config: Arc::new(Config::default()),
            registry: Arc::new(RwLock::new(SessionRegistry::new())),
            db: Arc::clone(&db),
            cmd_rx,
            cmd_tx,
            runtime: subsystems::EngineRuntimeState {
                torrent_chans: HashMap::from([(info_hash.clone(), torrent_tx)]),
                torrent_tasks: HashMap::new(),
                tier_controller: TierController::new(TierPolicy::default()),
                tier_last_active: HashMap::new(),
                pending_torrent_adds: HashSet::new(),
                pending_torrent_deletes: HashSet::new(),
                pending_torrent_promotions: std::collections::HashMap::new(),
            },
            services: subsystems::EngineSubsystems {
                dht_tx: None,
                resources: test_resource_governor(),
                network_budget: GlobalNetworkBudget::unlimited(),
                storage_jobs: StorageJobDispatcher::for_tests(),
                stats_cache: None,
            },
            pending_storage_moves: HashMap::new(),
            shutdown_reply: None,
        };

        // Make the first actor-side durable completion fail, then restore the
        // connection before the bounded retry is delivered.
        db.lock()
            .unwrap()
            .execute_batch("PRAGMA query_only = ON")
            .unwrap();
        storage_control::finish_storage_plan(
            &mut engine,
            "generic-storage-commit-retry".to_owned(),
            vec![(info_hash.clone(), false)],
            Vec::new(),
            Vec::new(),
            true,
            STORAGE_JOB_STATE_COMMIT_PENDING.to_owned(),
            None,
            vec![0],
            Some(7),
            false,
            true,
            0,
        )
        .await;
        tokio::time::timeout(Duration::from_secs(1), resume_seen_rx.recv())
            .await
            .expect("initial storage-plan resume was not delivered")
            .expect("resume observer channel closed");
        db.lock()
            .unwrap()
            .execute_batch("PRAGMA query_only = OFF")
            .unwrap();

        let retry = tokio::time::timeout(Duration::from_secs(2), engine.cmd_rx.recv())
            .await
            .expect("generic storage commit retry was not scheduled")
            .expect("engine command channel closed");
        if let EngineCmd::StoragePlanFinished {
            retry_attempt,
            terminal_state,
            resume_torrents,
            ..
        } = &retry
        {
            assert_eq!(*retry_attempt, 1);
            assert_eq!(terminal_state, STORAGE_JOB_STATE_COMMIT_PENDING);
            assert!(!resume_torrents);
        } else {
            panic!("generic storage commit retry had the wrong command");
        }
        assert!(engine.handle_cmd(retry).await);
        assert_eq!(
            rt_db::get_job(&db.lock().unwrap(), "generic-storage-commit-retry")
                .unwrap()
                .state,
            JOB_STATE_COMPLETED
        );
        assert!(
            tokio::time::timeout(Duration::from_millis(100), resume_seen_rx.recv())
                .await
                .is_err(),
            "durable completion retry replayed the torrent resume"
        );
        resume_task.abort();
    }

